function contactName(key){return window.WIKI_REVIEWED?.contactNames?.[key]||B.contacts[key]?.name||'特殊接触效果';}
function abilityTitle(key){if(key.startsWith('@contact:'))return contactName(key.slice(9));if(key.startsWith('@mass:'))return '质量与组成';if(key.startsWith('@attribute:'))return attribute(key.slice(11));if(key.startsWith('@rule:'))return combatRules[key.slice(6)]?.title||'战斗属性';const canonical=B.aliases[key]||window.WIKI_ABILITY_NAMES[key]||key,translated=name(canonical);if(translated!==canonical)return translated;const alias=Object.keys(B.aliases).find(n=>B.aliases[n]===canonical&&name(n)!==n);return name(alias||canonical);}
