 const fatigue=flag.match(/^fatigue_is_below_(.+)$/);if(fatigue)return '疲劳低于'+({active:'精神饱满',winded:'气喘吁吁',tired:'疲惫',very_tired:'非常疲惫',exhausted:'精疲力竭'}[fatigue[1]]||'指定状态');
 const mana=flag.match(/^mana_(above|below)_(\d+)%$/);if(mana)return `魔法之风${mana[1]==='above'?'高于':'低于'}${mana[2]}%`;
 if(flag==='mana_below_value_15')return '魔法之风低于15';if(flag==='mana_equal_or_above_value_15')return '魔法之风不少于15';
 const speed=flag.match(/^speed_(higher|lower)_than_50_percent_run_speed$/);if(speed)return `速度${speed[1]==='higher'?'高于':'低于'}奔跑速度的50%`;
 const mark=flag.match(/^(has|hasnt)_(.+)_mark$/);if(mark)return (mark[1]==='has'?'具有':'没有')+({khorne:'恐虐',nurgle:'纳垢',slaanesh:'色孽',tzeentch:'奸奇'}[mark[2]]||'神祇')+'印记';
 const souls=flag.match(/^(has|hasnt)_realm_of_souls_tier_(\d)$/);if(souls)return (souls[1]==='has'?'具有':'没有')+'灵魂国度第'+souls[2]+'阶段';
 const status=flag.match(/^is_(not_)?(on_fire|rampaging|under_bow_fire|under_gun_fire|under_missile_fire)$/);if(status)return (status[1]?'未':'正在')+({on_fire:'燃烧',rampaging:'狂暴',under_bow_fire:'遭受弓箭射击',under_gun_fire:'遭受枪械射击',under_missile_fire:'遭受远程射击'}[status[2]]);
