function attackTraits(a,interactive=true){if(!a)return '';const output=[];for(const [field,key] of [['magical','magic'],['flaming','flame']])if(a[field])output.push(interactive?referenceButton('@rule:'+key):tag(combatRules[key].title));if(a.contact)output.push(interactive?referenceButton('@contact:'+a.contact):tag(B.contacts[a.contact]?.name||'特殊接触效果'));return output.join(' ')||(interactive?referenceButton('@rule:normal'):tag('普通攻击'));}
function attackContent(a){if(!a)return '';const ex=a.explosion;return `<div class="ability-attack"><h4>${esc(a.kind||'投射物')}</h4><p>每发普通伤害 ${fmt(a.base)} · 破甲伤害 ${fmt(a.ap)}</p><div class="tags">${attackTraits(a,false)}</div>${a.contact?contactContent(a.contact,false):''}${ex?`<h4>爆炸伤害</h4><p>普通伤害 ${fmt(ex.base)} · 破甲伤害 ${fmt(ex.ap)} · 半径 ${fmt(ex.radius)}米</p><div class="tags">${attackTraits(ex,false)}</div>${ex.contact?contactContent(ex.contact,false):''}`:''}</div>`;}
function itemEffects(i){const refs=B.itemReferences?.[Z.itemKeys?.[i.name]]||[];return i.effects.map(text=>{const matches=refs.filter(r=>text===r.text||text.startsWith(r.text+' (')||text.startsWith(r.text+' for '));return matches.length?{text,refs:matches.flatMap(r=>r.refs)}:text;});}
function abilityEffect(value){
 const row=typeof value==='string'?{text:value}:value||{},text=String(row.text||''),pattern=/["“]([^"”]+)["”]/g;
 const originals=[...text.matchAll(/(?:(?:Passive ability|Ability|Spell):\s*)?["“]([^"”]+)["”]/gi)],translated=tr(text);
 let end=0,out='',m,index=0;const shown=new Set();
 while((m=pattern.exec(translated))){const original=originals[index++],key=original?.[1],records=window.WIKI_ABILITIES[key],explicit=/^(?:Passive ability|Ability|Spell):/i.test(original?.[0]||'');out+=esc(translated.slice(end,m.index));if(records||explicit){out+=referenceButton(key);for(const r of records||[])shown.add('ability:'+r.id);}else out+=esc(m[0]);end=pattern.lastIndex;}
 out+=esc(translated.slice(end));
 const refs=row.refs||B.effects[row.effect]||Object.entries(B.textReferences||{}).filter(([label])=>text===label||text.startsWith(label+' (')||text.startsWith(label+' for ')).flatMap(([,refs])=>refs);
 const extra=refs.filter(r=>!shown.has(r.kind+':'+r.id)).map(r=>referenceButton(r.kind==='ability'?r.id:'@'+r.kind+':'+r.id));
 if(/^(?:Enables flaming attacks|赋予火焰攻击)/i.test(text))extra.push(referenceButton('@rule:flame'));
 if(/^(?:Enables magical attacks|赋予魔法攻击|移除魔法攻击)/i.test(text))extra.push(referenceButton('@rule:magic'));
 if(/^Missile block chance:/i.test(text))extra.push(referenceButton('@rule:block'));
 if(extra.length)out+=`<span class="effect-references">${[...new Set(extra)].join(' ')}</span>`;return out;
}
function latestPatchNotes(...labels){const P=window.WIKI_PATCH_NOTES;const rows=P?.records.filter(r=>r.names.some(n=>labels.includes(n)));return rows?.length?`<details class="latest-patch"><summary>${P.version} 官方补丁调整</summary><ul class="effects">${rows.map(r=>`<li>${esc(r.text)}</li>`).join('')}</ul><p class="source-line">${esc(P.status)} · <a href="${esc(P.source)}" target="_blank" rel="noopener">官方 ${P.version} 公告</a></p></details>`:'';}
