function currentTree(){return X.trees.find(t=>t.id===treeVariant&&(!state.race||t.race===state.race))||X.trees.find(t=>!state.race||t.race===state.race);}
function factionName(k){return name(D.factions.find(f=>f.key===k)?.name||L.variants?.[k]||'派系专属');}
function techIcon(n){const path=A.technologies?.[n.icon]||A.technologies?.[n.key];return path?localImage(path,'tree-icon',''):'<span class="tree-icon missing-tech-icon" title="暂无对应科技图像" aria-label="暂无对应科技图像"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h6l2 2 2-2h6v14h-6l-2 2-2-2H4zM12 7v14"/></svg></span>'; }
function treeInfo(t,n){if(t.layout==='graph')return specialTreeInfo(t,n);if(!n)return '<p class="muted">选择科技，查看效果与研究条件。</p>';const nameReview=window.WIKI_REVIEWED?.nameReview?.[n.name.trim()],parents=t.links.filter(l=>l.child===n.id).map(l=>t.nodes.find(n=>n.id===l.parent)).filter(Boolean);return `<div class="tree-info-head">${techIcon(n)}<div><h3>${esc(name(n.name))}</h3><p>${fmt(n.cost)}研究点 · ${planned.has(n.id)?'规划为已研究':'未加入规划'}${n.faction?' · '+esc(factionName(n.faction)):''}</p></div><button class="button" data-plan-node="${esc(n.id)}">${planned.has(n.id)?'移出研究规划':'标为规划已研究'}</button></div>${parents.length?`<p>前置：${parents.map(p=>`<button class="text-button" data-tree-node="${esc(p.id)}">${esc(name(p.name))}</button>`).join('、')}</p>`:'<p>无已列出的前置科技。</p>'}<p class="muted">研究状态为本页规划。</p>${n.effects.length?effects(n.effects):'<p>暂无效果说明。</p>'}<details><summary>条件与来源</summary>${nameReview?`<p>名称来源：${esc(nameReview.status)} · <span lang="en">${esc(n.name)}</span></p><p><a href="${esc(nameReview.source)}" target="_blank" rel="noopener">名称对应原文</a></p>`:''}${traceValue('科技 ID',n.key)}${traceValue('节点 ID',n.id)}${traceValue('科技树 ID',t.id)}${traceValue('派系限制',n.faction)}${traceValue('UI分组',n.group)}${traceValue('额外资源成本 ID',n.resource)}${traceValue('每回合费用',n.costPerRound!=='0'?n.costPerRound:'')}${traceValue('食物费用',n.foodCost!=='0'?n.foodCost:'')}${traceValue('建筑关联字段',n.building)}<p class="muted">建筑字段可能为历史关联或占位值，不单凭此字段断定当前补丁研究前置。</p>${n.effects.map(e=>`${traceValue('效果 ID',e.effect)}${traceValue('范围',e.scope)}<p>原值：${fmt(e.value)}</p>`).join('')}<a href="${rawTableLink('technology_nodes')}" target="_blank" rel="noopener">游戏科技节点表 · 9.0</a> · <a href="${rawTableLink('technology_node_links')}" target="_blank" rel="noopener">前置连线表</a></details>`;}
function baseTreeNodes(t){return t.nodes.filter(n=>(!treeFaction||!n.faction||n.faction===treeFaction)&&(!state.q||searchable(n,state.q)));}
function technologyPages(t){
 const nodes=baseTreeNodes(t),pages=[{id:'',label:'全部科技',test:()=>true}];
 if(t.layout==='graph'){
  for(const key of new Set(nodes.map(n=>n.group)))pages.push({id:'group:'+key,label:t.groups[key]||'升级分支',test:n=>n.group===key});
 }else if(t.race==='dwarfs'){
  pages.push({id:'civil',label:'内政',test:n=>n.key.includes('_dwf_civ_')},{id:'military',label:'军事',test:n=>n.key.includes('_dwf_mil_')});
 }else if(t.race==='empire'){
  pages.push({id:'military',label:'军事',test:n=>/^emp_(art|machines|cav|mil|missile|enemies|state_troops)/.test(n.group)},
   {id:'civil',label:'内政',test:n=>/^emp_(aca|eco|dip|com)/.test(n.group)},
   {id:'unique',label:'派系专属',test:n=>/^emp_unique/.test(n.group)});
 }else{
  const groups=new Map();for(const n of nodes){const label=window.TECH_GROUP_LABELS[n.group]||(n.group?'其他分支':'共享科技');if(!groups.has(label))groups.set(label,new Set());groups.get(label).add(n.group);}
  if(groups.size>1)for(const [label,keys] of groups)pages.push({id:'group:'+([...keys].join('|')||'shared'),label,test:n=>keys.has(n.group)});
 }
 return pages.map(p=>({...p,count:nodes.filter(p.test).length})).filter(p=>!p.id||p.count);
}
function treeNodes(t){const p=technologyPages(t).find(p=>p.id===treePage);return baseTreeNodes(t).filter(p?.test||(()=>true));}
function compactTreeLayout(nodes){
 const pos=new Map(),groups=[],byGroup=new Map();
 for(const n of nodes){const key=n.group||'';if(!byGroup.has(key))byGroup.set(key,[]);byGroup.get(key).push(n);}
 let y=18,width=360;
 for(const [key,items] of byGroup){
  const coord=n=>n.tier*196+n.offsetX,rows=n=>n.indent*110+n.offsetY;
  const collapse=(values,gap)=>{const unique=[...new Set(values)].sort((a,b)=>a-b),map=new Map();let prev=unique[0]||0,at=0;for(const v of unique){at+=Math.min(v-prev,gap);map.set(v,at);prev=v;}return map;};
  const xs=collapse(items.map(coord),196),ys=collapse(items.map(rows),110),placed=[];
  for(const n of [...items].sort((a,b)=>coord(a)-coord(b)||rows(a)-rows(b))){const p={x:24+xs.get(coord(n)),y:y+46+ys.get(rows(n))};let clash;while((clash=placed.find(q=>Math.abs(p.x-q.x)<184&&Math.abs(p.y-q.y)<98)))p.y=clash.y+110;pos.set(n.id,p);placed.push(p);}
  const right=Math.max(360,...placed.map(p=>p.x+196)),bottom=Math.max(y+150,...placed.map(p=>p.y+98));
  groups.push({key,label:window.TECH_GROUP_LABELS[key]||(key?'科技分支':'共享科技'),x:12,y,width:right-12,height:bottom-y,count:items.length});width=Math.max(width,right+12);y=bottom+18;
 }
 return {pos,width,height:Math.max(170,y),groups};
}
function fitTree(){
 window.WIKI_TREE_VIEW.fit('tech');
 const canvas=$('.pyramid-canvas'),box=$('.tech-scroll');
 if(canvas&&box&&!canvas.dataset.started&&canvas.dataset.startX){
  const scale=Number(canvas.dataset.scale)||1;
  box.scrollLeft=(Number(canvas.dataset.startX)+26)*scale-box.clientWidth/2;
  box.scrollTop=(Number(canvas.dataset.startY)+26)*scale-box.clientHeight/2;
  canvas.dataset.started='true';
 }
}
function technologyTitle(t){return t.title||L.variants[t.id]||raceMap[t.race]?.zh+' · 科技树';}
function technologyEntries(race='',faction=''){
 let trees=X.trees.filter(t=>!race||t.race===race);const entries=[];
 if(faction&&trees.some(t=>t.faction===faction))trees=trees.filter(t=>t.faction===faction);
 for(const t of trees){
  if(faction&&t.faction&&t.faction!==faction)continue;
  if(!faction||!t.nodes.some(n=>n.faction===faction))entries.push({tree:t.id,faction:t.faction||faction,race:t.race,label:technologyTitle(t)});
  if(t.layout==='graph')continue;
  for(const key of new Set(t.nodes.map(n=>n.faction).filter(Boolean))){
   if(key===t.faction||(faction&&key!==faction))continue;
   const leader=D.factions.find(f=>f.key===key)?.lord;
   entries.push({tree:t.id,faction:key,race:t.race,label:factionName(key)+' · 专属分支'+(leader?'（'+name(leader)+'）':'')});
  }
 }
 if(faction&&entries.some(e=>e.faction===faction))return entries.filter(e=>e.faction===faction);
 return entries;
}
function specialTreeLinks(race,faction=''){
 const entries=technologyEntries(race,faction);if(!entries.length)return '';
 return `<section class="technology-entry-links"><h3>科技与特殊升级</h3><div class="detail-actions">${entries.map(e=>`<a class="button" href="#technology/${encodeURIComponent(e.tree)}/${encodeURIComponent(e.faction)}">${esc(e.label)}</a>`).join('')}</div></section>`;
}
function graphTreeLayout(t,nodes){
 if(!nodes.length)return {pos:new Map(),width:360,height:380,groups:[]};
 const factor=2.65,minX=Math.min(...nodes.map(n=>n.graphX)),minY=Math.min(...nodes.map(n=>n.graphY));
 const pos=new Map(nodes.map(n=>[n.id,{x:42+(n.graphX-minX)*factor,y:42+(n.graphY-minY)*factor}]));
 return {pos,width:Math.max(360,...[...pos.values()].map(p=>p.x+90)),height:Math.max(380,...[...pos.values()].map(p=>p.y+90)),groups:[]};
}
function specialTreeInfo(t,n){
 if(!n)return '<p>选择符印，查看效果、相连节点与解锁条件。</p>';
 const neighbors=t.links.filter(l=>l.child===n.id||l.parent===n.id).map(l=>t.nodes.find(x=>x.id===(l.child===n.id?l.parent:l.child))).filter(Boolean);
 const sourceTable=k=>`https://github.com/Shazbot/WH3-Dump/blob/${t.rawCommit}/db/${k}_tables/data__.tsv`;
 return `<div class="tree-info-head"><div><h3>${esc(n.name)}</h3><p>${n.id===t.origin?'起始符印 · 默认激活':`${fmt(n.cost)} ${esc(t.resourceLabel)} · ${planned.has(n.id)?'已加入规划':'未加入规划'}`}</p></div>${n.id===t.origin?'':`<button class="button" data-plan-node="${esc(n.id)}">${planned.has(n.id)?'移出规划':'加入赋能规划'}</button>`}</div>
 <div class="tags">${[...new Set([t.groups[n.group],t.groups[n.cluster]])].filter(Boolean).map(v=>tag(v)).join('')}${n.type==='gate'?tag('解锁门槛','gold'):''}</div>
 ${n.threshold?`<p><strong>解锁门槛：已赋能符印达到 ${fmt(n.threshold)} 个。</strong></p>`:''}
 ${n.effects.length?effects(n.effects.filter(e=>!e.originalText?.startsWith('[HIDDEN'))):n.id===t.origin?'<p>从此符印向外连接赋能；起始节点没有独立属性加成。</p>':'<p>此节点用于连接或解锁后续路线，效果列表未列出独立属性加成。</p>'}
 <details><summary>相连节点 · ${neighbors.length}</summary><div class="graph-neighbors">${neighbors.map(p=>`<button class="text-button" data-tree-node="${esc(p.id)}">${esc(p.name)}</button>`).join('')}</div></details>
 <details><summary>数据与来源</summary><p>节点、连接、费用与效果采用固定 9.0 游戏表。后续补丁差异尚未逐节点合并。</p><p>中文名称为编辑译名；尚未取得可核对的官方中文本地化。图标待补，画布上的形状仅区分节点类型。</p><p lang="en">${esc(n.originalName)}</p>${traceValue('升级 ID',n.key)}${traceValue('图节点 ID',n.id)}${traceValue('原包图标路径',n.gameIcon)}${traceValue('效果列表 ID',n.effectList)}${n.effects.map(e=>`${traceValue('效果 ID',e.effect)}${traceValue('范围 ID',e.scope)}<p>原值：${fmt(e.value)}</p>`).join('')}<p><a href="${sourceTable('ui_graph_nodes')}" target="_blank" rel="noopener">原始节点与坐标</a> · <a href="${sourceTable('ui_graph_node_links')}" target="_blank" rel="noopener">连接表</a> · <a href="${sourceTable('campaign_effect_list_effect_junctions')}" target="_blank" rel="noopener">效果关联表</a> · <a href="${esc(t.source)}" target="_blank" rel="noopener">官方机制介绍</a></p></details>`;
}
function techPage(){
 const t=currentTree();if(!t)return header('科技树','该种族没有传统科技树，请查看神耀、身体部件及专属机制。')+subtabs([['','兵种数据'],['techs','科技树']],state.sub)+`<div class="filters">${raceSelect()}</div>`;
 treeVariant=t.id;const graph=t.layout==='graph',restricted=[...new Set(t.nodes.map(n=>n.faction).filter(Boolean))],factions=restricted.length?[...new Set([...D.factions.filter(f=>f.race===t.race).map(f=>f.key).filter(Boolean),...restricted])]:[];
 if(treeFaction==='__auto__'||(treeFaction&&!factions.includes(treeFaction)))treeFaction='';
 const treeRoute='#technology/'+encodeURIComponent(t.id)+'/'+encodeURIComponent(treeFaction);if(!location.hash.startsWith('#entry/')&&location.hash!==treeRoute)history.replaceState(history.state,'',treeRoute);
 const pages=technologyPages(t);if(!pages.some(p=>p.id===treePage))treePage='';
 const nodes=treeNodes(t),drawingNodes=graph&&nodes.length?t.nodes:nodes,matchedIds=new Set(nodes.map(n=>n.id)),{pos,width:w,height:h,groups}=graph?graphTreeLayout(t,drawingNodes):compactTreeLayout(nodes);
 const inspected=nodes.find(n=>n.id===treeSelected)||(graph?(nodes.find(n=>n.id===t.origin)||nodes[0]):null);
 const edges=t.links.filter(l=>l.visible&&pos.has(l.parent)&&pos.has(l.child));
 const active=n=>planned.has(n.id)||graph&&n.id===t.origin?'researched':graph?'available':t.links.some(l=>l.child===n.id&&!planned.has(l.parent))?'pending':'available';
 const lines=edges.map(l=>{const a=pos.get(l.parent),b=pos.get(l.child);if(graph)return `<path d="M${a.x+26},${a.y+26}L${b.x+26},${b.y+26}" class="${planned.has(l.parent)&&planned.has(l.child)?'done':''}"/>`;const x1=a.x+174,y1=a.y+41,x2=b.x,y2=b.y+41,m=(x1+x2)/2;return `<path d="M${x1},${y1}H${m}V${y2}H${x2}" class="${planned.has(l.parent)?'done':''}"/>`;}).join('');
 const trees=X.trees.filter(x=>!state.race||x.race===state.race),variants=state.race?trees:[],entries=technologyEntries(state.race);
 const pageTabs=pages.length>1?`<div class="tree-pages" role="tablist" aria-label="科技分类">${pages.map(p=>`<button type="button" role="tab" aria-selected="${p.id===treePage}" tabindex="${p.id===treePage?0:-1}" aria-controls="technology-panel" data-tree-page="${esc(p.id)}">${esc(p.label)} <span>${p.count}</span></button>`).join('')}</div>`:'';
 const start=pos.get(inspected?.id)||pos.get(t.origin)||pos.values().next().value;
 return header(graph?t.title:'科技树',graph?'以赋能符印解锁的专用升级网络；保留游戏节点坐标与连接关系。':'研究路线、派系分支与科技效果。')+subtabs([['','兵种数据'],['techs','科技树']],state.sub)+
 `<div class="filters">${raceSelect()}${!state.race?`<select id="tree-variant" aria-label="选择科技树">${trees.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${esc(technologyTitle(x))}</option>`).join('')}</select>`:''}${factions.length?`<select id="tree-faction" aria-label="科技派系"><option value="" ${treeFaction===''?'selected':''}>全部派系分支</option>${factions.map(f=>`<option value="${esc(f)}" ${treeFaction===f?'selected':''}>${esc(factionName(f))}</option>`).join('')}</select>`:''}<span class="result-count">${nodes.length}${graph&&nodes.length<t.nodes.length?' / '+t.nodes.length:''} ${graph?'个符印':'项科技'}</span></div>`+
 `<details class="technology-directory"><summary>科技树与派系专属分支 · ${entries.length} 个入口</summary><label>查找派系或科技树<input type="search" data-technology-search placeholder="例如：黑色金字塔、奈芙瑞塔、奥斯坦基娅"></label><div class="technology-entry-list">${entries.map(e=>`<a href="#technology/${encodeURIComponent(e.tree)}/${encodeURIComponent(e.faction)}" data-technology-entry>${esc(e.label)}<small>${raceMap[e.race]?.zh||''}</small></a>`).join('')}</div><p data-technology-empty hidden>没有匹配的科技树或派系分支。</p></details>`+
 `${variants.length>1?`<div class="tree-variants" aria-label="派系科技树">${variants.map(v=>`<button class="${v.id===t.id?'active':''}" data-tree-variant="${esc(v.id)}">${esc(technologyTitle(v))}</button>`).join('')}</div>`:''}${pageTabs}`+
 (graph?`<p class="graph-guide">连接已赋能的符印，向外扩展路线；分组与搜索以高亮显示，保留完整网络。<span>数据：9.0 · 中文名称为编辑译名 · 图标待补</span></p>`:'')+
 `<div class="tree-toolbar"><span>${graph?'起始符印默认激活；节点形状区分普通、关键与门槛节点。':'<i class="tree-key available"></i>无未研究前置 <i class="tree-key pending"></i>含未研究前置'} <i class="tree-key researched"></i>规划已${graph?'赋能':'研究'}</span><div class="tree-view-controls">${window.WIKI_TREE_VIEW.controls('tech')}<button id="clear-tree-plan" class="button">清空规划</button></div></div>`+
 `<div id="technology-panel" role="tabpanel" aria-label="${esc(pages.find(p=>p.id===treePage)?.label||'全部科技')}"><div class="tech-scroll" tabindex="0" aria-label="科技树，可滚动"><div class="tech-stage"><div class="tech-canvas ${graph?'pyramid-canvas':''}" data-width="${w}" data-height="${h}" ${graph&&start?`data-start-x="${start.x}" data-start-y="${start.y}"`:''} style="width:${w}px;height:${h}px"><svg class="tree-lines" width="${w}" height="${h}" aria-hidden="true">${lines}</svg>${groups.map(g=>`<section class="tree-group tech-group" style="left:${g.x}px;top:${g.y}px;width:${g.width}px;height:${g.height}px"><h3>${esc(g.label)} <small>${g.count} 项</small></h3></section>`).join('')}${drawingNodes.map(n=>{const p=pos.get(n.id),cost=graph?`${n.cost} ${t.resourceLabel}`:`${fmt(n.cost)}研究点`;return `<button class="${graph?'pyramid-node node-'+n.type:'tech-node'} ${graph&&!matchedIds.has(n.id)?'context-node':''} ${active(n)} ${treeSelected===n.id?'selected':''}" style="left:${p.x}px;top:${p.y}px" data-tree-node="${esc(n.id)}" aria-label="${esc(n.name)}，${cost}" title="${esc(name(n.name))} · ${cost}${n.threshold?' · '+n.threshold+'个已赋能符印门槛':''}">${graph?`<span class="pyramid-node-marker" aria-hidden="true">${n.id===t.origin?'始':n.type==='gate'?n.threshold:n.type==='key'?'◆':n.type==='major'?'◇':'·'}</span>`:techIcon(n)+`<span>${esc(name(n.name))}</span>`}</button>`;}).join('')}${nodes.length?'':'<p class="tree-empty">没有匹配的节点，请修改搜索词或分类。</p>'}</div></div></div></div>`+
 `<p class="kbd-hint">点击节点查看详情；Ctrl＋滚轮缩放，方向键滚动画布，＋ / − 缩放，0 恢复原始比例。${graph?'赋能标记仅作路线规划，不模拟战役的实际资源或可解锁状态。':'研究标记仅用于规划。'}</p><section id="tree-inspector" class="tree-inspector">${treeInfo(t,inspected)}</section>`;
}


function bonusApplies(b,u){if(b.category==='victory')return b.races.includes(u.race);if(b.races.length&&!b.races.includes(u.race))return false;if(b.category==='purchase')return b.units.some(x=>x.unit===u.id);return b.rows.some(r=>(X.effectMaps[r.effect]||[]).some(m=>m.unit===u.id||X.sets[m.set]?.includes(u.id)));}
function bonusRecord(b,u=null){const rows=u&&b.category!=='victory'?b.rows.filter(r=>(X.effectMaps[r.effect]||[]).some(m=>m.unit===u.id||X.sets[m.set]?.includes(u.id))||b.category==='purchase'):b.rows;return `<article class="bonus-record"><div class="tags">${tag(bonusCats[b.category])}${tag(b.kind)}${b.owner?tag(name(b.owner)):''}</div><h4>${esc(name(b.name))}</h4>${b.units?.length?`<p class="cell-sub">适用兵种：${[...new Set(b.units.map(x=>D.units.find(v=>v.id===x.unit)).filter(Boolean).map(v=>name(v.name)))].map(esc).join("、")||"当前目录未匹配，展开核对单位 ID"}</p>`:""}${b.system?`<p>${esc(b.system)}</p>`:''}<p>${esc(b.condition)}</p>${b.rank?`<p>角色解锁等级：${b.rank}</p>`:''}${b.factions?.length?`<p>所属派系：${b.factions.map(id=>esc(name(D.factions.find(f=>f.id===id)?.name||id))).join('、')}</p>`:''}<details><summary>效果、单位限制与来源</summary>${effects(rows.map(r=>({...r,text:`${r.level?r.level+'级 · ':''}${r.text}`})))}${rows.map(r=>`${traceValue('效果 ID',r.effect)}${traceValue('作用范围',r.scope)}<p>原值：${fmt(r.value)}${r.level?' · 技能等级 '+r.level:''}</p>${(X.effectMaps[r.effect]||[]).map(m=>traceValue('单位组',m.set)+traceValue('单位 ID',m.unit)+(m.attribute?`<p>属性：${esc(attribute(m.attribute))}</p>`:'')+traceValue('能力 ID',m.ability)).join('')}`).join('')}${b.acquisition?`<p>取得条件：${esc(tr(b.acquisition))}</p>`:''}${b.removal?`<p>失效条件：${esc(tr(b.removal))}</p>`:''}${traceValue('记录 ID',b.id)}${traceValue('资源成本 ID',b.cost)}${traceValue('前置组 ID',b.prerequisite)}${b.units?.length?`<p>实际单位：${b.units.filter(x=>D.units.some(u=>u.id===x.unit)).map(x=>{const u=D.units.find(u=>u.id===x.unit);return esc(name(u.name))+(x.exclusive?'（互斥）':'');}).join('、')||'没有在当前兵种目录中匹配'}</p>`:''}${b.banned?.length?`<p>禁用派系：${b.banned.map(k=>esc(factionName(k))).join('、')}</p><details><summary>禁用派系原始ID</summary>${b.banned.map(k=>traceValue('派系',k)).join('')}</details>`:''}<p>${b.table?`<a href="${rawTableLink(b.table)}" target="_blank" rel="noopener">固定9.0原始关联表</a>`:''}${b.source?` · <a href="${esc(b.source)}" target="_blank" rel="noopener">条目参考</a>`:''}</p>${b.ownerId?btn(b.ownerKind,b.ownerId,'查看领主技能'):''}</details></article>`;}
function permanentPanel(u){const rows=X.bonuses.filter(b=>bonusApplies(b,u));const groups=Object.fromEntries(Object.keys(bonusCats).map(k=>[k,rows.filter(b=>b.category===k)]));return `<h3>其他永久与持续加成 · ${rows.length}条关联</h3><p class="muted">按取得渠道查看，并满足各项保持条件；此处加成不自动加入科技估算。</p><div class="permanent-groups">${Object.entries(groups).filter(([k,v])=>v.length).map(([k,v])=>`<details><summary>${bonusCats[k]} · ${v.length}</summary>${v.map(b=>bonusRecord(b,u)).join('')}</details>`).join('')}</div><p><button class="button" data-race-detail="${u.race}">查看种族机制与取得途径</button></p>`;}
